import static org.junit.Assert.assertEquals;

import org.junit.Test;
import org.mockito.Mockito;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.utill.Map;

public class CommentsConfigurationTest {

    @Test
    public void setCommentEmptyStringTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();

        commentsConfiguration.setComment("", "Test comment");
        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();
        List<String> expectedComments = new ArrayList<>();
        expectedComments.add("Test comment");

        assertEquals(expectedComments, allComments.get(""));
    }

    @Test
    public void setCommentMultipleLinesTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();

        commentsConfiguration.setComment("path", "line1", "line2", "line3");
        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();
        List<String> expectedComments = new ArrayList<>();
        expectedComments.add("line1");
        expectedComments.add("line2");
        expectedComments.add("line3");

        assertEquals(expectedComments, allComments.get("path"));
    }

    @Test
    public void setCommentOverrideExistingTest() {
        Map<String, List<String>> initialComments = new HashMap<>();
        initialComments.put("path", Arrays.asList("old comment"));
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(initialComments);

        commentsConfiguration.setComment("path", "new comment");
        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();
        List<String> expectedComments = new ArrayList<>();
        expectedComments.add("new comment");

        assertEquals(expectedComments, allComments.get("path"));
    }

    @Test
    public void getAllCommentsTest() {
        Map<String, List<String>> initialComments = new HashMap<>();
        List<String> comments = new ArrayList<>();
        comments.add("comment1");
        comments.add("comment2");
        initialComments.put("path", comments);
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(initialComments);

        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();

        assertEquals(initialComments, allComments);
    }
}
